internal static class CompanionTheme {
 internal static readonly Brush Background=Color("#121211"),Surface=Color("#1D1D1A"),Raised=Color("#25241F"),Line=Color("#3A3529"),Gold=Color("#DABB7B"),Ink=Color("#F4EDDE"),Muted=Color("#B3AC9C"),Green=Color("#9AC7A8");
 internal static Brush Color(string value){return new SolidColorBrush((System.Windows.Media.Color)ColorConverter.ConvertFromString(value));}
 internal static TextBlock Label(string value,double size=10){return new TextBlock{Text=value,Foreground=Muted,FontSize=size,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,6)};}
 internal static Border Card(UIElement content,int padding=16){return new Border{Child=content,Background=Surface,BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(14),Padding=new Thickness(padding),Margin=new Thickness(0,0,0,12)};}
 internal static Border Shell(UIElement content){return new Border{Child=content,Background=Background,BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(18),Padding=new Thickness(18),SnapsToDevicePixels=true};}
 internal static TextBlock Heading(string value,double size=25){return new TextBlock{Text=value,FontFamily=new FontFamily("Palatino Linotype"),FontSize=size,Foreground=Ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,10)};}
 internal static TextBlock Number(double size=32){return new TextBlock{Text="00:00:00",FontFamily=new FontFamily("Consolas"),FontSize=size,FontWeight=FontWeights.SemiBold,Foreground=Ink,Margin=new Thickness(0,3,0,6)};}
 internal static Grid Pair(UIElement left,UIElement right){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());if(left!=null)grid.Children.Add(left);if(right!=null){Grid.SetColumn(right,1);grid.Children.Add(right);}return grid;}
 internal static Expander Fold(string title,UIElement content,bool open=false){return new Expander{Header=title,Content=content,IsExpanded=open,Margin=new Thickness(0,0,0,10)};}
 internal static DockPanel Header(Window owner,string title,bool testing){var header=new DockPanel{Margin=new Thickness(0,0,0,16)};var close=CompanionWindow.Button("×",owner.Close);close.ToolTip="Fermer";close.Width=32;close.Height=32;close.Padding=new Thickness(0);close.Margin=new Thickness(0);System.Windows.Automation.AutomationProperties.SetName(close,"Fermer la fenêtre");DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);var minimize=CompanionWindow.Button("−",()=>owner.WindowState=WindowState.Minimized);minimize.ToolTip="Réduire";minimize.Width=32;minimize.Height=32;minimize.Padding=new Thickness(0);minimize.Margin=new Thickness(0,0,6,0);DockPanel.SetDock(minimize,Dock.Right);header.Children.Add(minimize);var caption=new StackPanel{Orientation=Orientation.Horizontal,Cursor=Cursors.SizeAll};caption.Children.Add(new TextBlock{Text="◈",FontSize=24,Foreground=Gold,Margin=new Thickness(0,0,10,0),VerticalAlignment=VerticalAlignment.Center});var stack=new StackPanel();stack.Children.Add(new TextBlock{Text="COMPAGNON",FontFamily=GuideAssets.TitleFont,FontSize=22,Foreground=Gold,Margin=new Thickness(0,0,0,4)});stack.Children.Add(new TextBlock{Text=title,FontSize=15,FontWeight=FontWeights.SemiBold,Foreground=Ink});caption.Children.Add(stack);caption.MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){if(e.LeftButton==MouseButtonState.Pressed&&!testing)owner.DragMove();};header.Children.Add(caption);return header;}
 internal static Window Dialog(Window owner,string title,int width,int height,out StackPanel panel){var dialog=new Window{Title=title,Width=width,Height=height,Owner=owner,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Brushes.Transparent,AllowsTransparency=true,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,Resources=owner.Resources,Foreground=Ink,FontFamily=new FontFamily("Segoe UI")};var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.Children.Add(Header(dialog,title,false));panel=new StackPanel();var scroll=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);grid.Children.Add(scroll);dialog.Content=Shell(grid);return dialog;}
 internal static bool Confirm(Window owner,string title,string message){StackPanel panel;var dialog=Dialog(owner,title,380,300,out panel);bool accepted=false;panel.Children.Add(CompanionWindow.Text(message,13));panel.Children.Add(CompanionWindow.Button("Continuer",()=>{accepted=true;dialog.Close();},true));panel.Children.Add(CompanionWindow.Button("Annuler",dialog.Close));dialog.ShowDialog();return accepted;}
